package com.lendup.reservas.integration;
import static org.junit.jupiter.api.Assertions.*; import com.lendup.reservas.application.exception.BusinessConflictException; import com.lendup.reservas.application.port.out.CatalogoPort; import com.lendup.reservas.application.service.ReservationApplicationService; import com.lendup.reservas.domain.model.*; import com.lendup.reservas.infrastructure.messaging.LoanEventConsumer; import com.lendup.reservas.infrastructure.persistence.entity.SolicitudEntity; import com.lendup.reservas.infrastructure.persistence.repository.*; import com.lendup.reservas.support.TestAuthConfiguration; import java.math.BigDecimal; import java.time.*; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicReference; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.*; import org.springframework.context.annotation.*; import org.springframework.test.context.*; import org.testcontainers.junit.jupiter.*; import org.testcontainers.mysql.MySQLContainer; import tools.jackson.databind.json.JsonMapper;
@Testcontainers(disabledWithoutDocker=true) @ActiveProfiles("test") @Import({TestAuthConfiguration.class,MySqlConcurrencyIT.CatalogStubConfiguration.class}) @SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.MOCK,properties={"spring.rabbitmq.listener.simple.auto-startup=false","lendup.outbox.relay-delay-ms=3600000","spring.datasource.hikari.maximum-pool-size=25","springdoc.api-docs.enabled=true","springdoc.swagger-ui.enabled=true"})
class MySqlConcurrencyIT { @Container static final MySQLContainer mysql=new MySQLContainer("mysql:8.4").withDatabaseName("lendup_reservas").withUsername("test").withPassword("test");
  @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",mysql::getJdbcUrl);r.add("spring.datasource.username",mysql::getUsername);r.add("spring.datasource.password",mysql::getPassword);}
  @Autowired ReservationApplicationService service; @Autowired SolicitudJpaRepository solicitudes; @Autowired ReservaJpaRepository reservas; @Autowired AgendaJpaRepository agendas; @Autowired OutboxJpaRepository outbox; @Autowired AuditJpaRepository audits; @Autowired ProcessedEventJpaRepository processed; @Autowired LoanEventConsumer consumer; @Autowired JsonMapper json; @Autowired org.springframework.transaction.PlatformTransactionManager transactionManager; @Autowired org.springframework.web.context.WebApplicationContext webContext; @Autowired TestCatalogo catalogo;
  UUID lender,publication; @BeforeEach void setup(){processed.deleteAll();outbox.deleteAll();audits.deleteAll();reservas.deleteAll();solicitudes.deleteAll();agendas.deleteAll();lender=UUID.randomUUID();publication=UUID.randomUUID();catalogo.owner.set(lender);}
  @Test void veinteAceptacionesSuperpuestasConfirmanExactamenteUna()throws Exception{List<UUID> ids=new ArrayList<>();for(int i=0;i<20;i++)ids.add(pending(UUID.randomUUID()));ExecutorService pool=Executors.newFixedThreadPool(20);try{List<Future<Boolean>> futures=ids.stream().map(id->pool.submit(()->{try{service.aceptarSolicitud(lender,id);return true;}catch(BusinessConflictException e){return false;}})).toList();int accepted=0;for(Future<Boolean> f:futures)if(f.get(30,TimeUnit.SECONDS))accepted++;assertEquals(1,accepted);assertEquals(1,reservas.count());assertEquals(1,agendas.count());}finally{pool.shutdownNow();}}
  @Test void mismaSolicitudAceptadaDosVecesCreaUnaReserva()throws Exception{UUID id=pending(UUID.randomUUID());ExecutorService pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->attempt(id));var b=pool.submit(()->attempt(id));assertEquals(1,(a.get()?1:0)+(b.get()?1:0));assertEquals(1,reservas.count());}finally{pool.shutdownNow();}}
  @Test void cancelacionPendienteMantieneElPeriodoBloqueado(){UUID first=pending(UUID.randomUUID());UUID reservation=service.aceptarSolicitud(lender,first).id();service.solicitarCancelacionReserva(lender,false,reservation,"Cambio", "corr");UUID second=pending(UUID.randomUUID());assertThrows(BusinessConflictException.class,()->service.aceptarSolicitud(lender,second));}
  @Test void reservaYOutboxSeReviertenJuntasSiFallaLaTransaccion(){UUID id=pending(UUID.randomUUID());var tx=new org.springframework.transaction.support.TransactionTemplate(transactionManager);assertThrows(RuntimeException.class,()->tx.executeWithoutResult(ignored->{service.aceptarSolicitud(lender,id);throw new RuntimeException("fallo forzado");}));assertEquals(0,reservas.count());assertEquals(0,outbox.count());assertEquals(EstadoSolicitud.PENDIENTE,solicitudes.findById(id).orElseThrow().getEstado());}
  @Test void consumidorDeduplicaElMismoEvento()throws Exception{UUID request=pending(UUID.randomUUID());UUID reservation=service.aceptarSolicitud(lender,request).id();service.solicitarCancelacionReserva(lender,false,reservation,"Cambio","corr");byte[] event=loanEvent(UUID.randomUUID(),"PrestamoCancelado",1,reservation);consumer.consume(event);consumer.consume(event);assertEquals(EstadoReserva.CANCELADA,reservas.findById(reservation).orElseThrow().getEstado());assertEquals(1,processed.count());assertEquals(3,outbox.count());}
  @Test void consumidorDeduplicaConcurrentementeElMismoEvento()throws Exception{UUID request=pending(UUID.randomUUID());UUID reservation=service.aceptarSolicitud(lender,request).id();service.solicitarCancelacionReserva(lender,false,reservation,"Cambio","corr");byte[] event=loanEvent(UUID.randomUUID(),"PrestamoCancelado",1,reservation);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> first=pool.submit(()->consumeUnchecked(event));Future<?> second=pool.submit(()->consumeUnchecked(event));first.get(10,TimeUnit.SECONDS);second.get(10,TimeUnit.SECONDS);assertEquals(EstadoReserva.CANCELADA,reservas.findById(reservation).orElseThrow().getEstado());assertEquals(1,processed.count());assertEquals(3,outbox.count());}finally{pool.shutdownNow();}}
  @Test void eventosEmitidosMantienenVersionAgregadaMonotona()throws Exception{UUID request=pending(UUID.randomUUID());UUID reservation=service.aceptarSolicitud(lender,request).id();service.solicitarCancelacionReserva(lender,false,reservation,"Cambio","corr");consumer.consume(loanEvent(UUID.randomUUID(),"PrestamoCancelado",1,reservation));List<Long> versions=outbox.findAll().stream().filter(e->e.getAggregateId().equals(reservation)).map(e->e.getAggregateVersion()).sorted().toList();assertEquals(List.of(1L,2L,3L),versions);}
  @Test void eventoFueraDeOrdenNoRevierteUnaDecisionMasNueva()throws Exception{UUID request=pending(UUID.randomUUID());UUID reservation=service.aceptarSolicitud(lender,request).id();service.solicitarCancelacionReserva(lender,false,reservation,"Cambio","corr");consumer.consume(loanEvent(UUID.randomUUID(),"CancelacionRechazada",3,reservation));consumer.consume(loanEvent(UUID.randomUUID(),"PrestamoCancelado",2,reservation));assertEquals(EstadoReserva.CONFIRMADA,reservas.findById(reservation).orElseThrow().getEstado());assertEquals(2,processed.count());}
  @Test void solicitudesDuplicadasPendientesSeRechazanSinInventarConsentimiento(){UUID borrower=UUID.randomUUID();LocalDateTime from=LocalDateTime.of(2026,11,10,9,0),to=from.plusDays(1);var created=service.crearSolicitud(borrower,publication,from,to);assertNull(created.condicionesAceptadasEn());assertThrows(BusinessConflictException.class,()->service.crearSolicitud(borrower,publication,from,to));assertEquals(1,solicitudes.count());}
  @Test void comprobacionPreventivaRechazaPeriodoYaComprometido(){UUID request=pending(UUID.randomUUID());service.aceptarSolicitud(lender,request);assertThrows(BusinessConflictException.class,()->service.crearSolicitud(UUID.randomUUID(),publication,LocalDateTime.of(2026,11,10,10,0),LocalDateTime.of(2026,11,11,10,0)));}
  @Test void soloParticipantesContextualesPuedenDecidirSolicitudes(){UUID borrower=UUID.randomUUID(),request=pending(borrower);UUID outsider=UUID.randomUUID();assertThrows(com.lendup.reservas.application.exception.ForbiddenException.class,()->service.aceptarSolicitud(borrower,request));assertThrows(com.lendup.reservas.application.exception.ForbiddenException.class,()->service.rechazarSolicitud(outsider,request,"sin autorización"));assertThrows(com.lendup.reservas.application.exception.ForbiddenException.class,()->service.cancelarSolicitud(lender,request,"sin autorización"));assertEquals(EstadoSolicitud.PENDIENTE,solicitudes.findById(request).orElseThrow().getEstado());}
  @Test void eventosInvalidosNoSeRegistranComoProcesados(){assertThrows(IllegalArgumentException.class,()->consumer.consume(json.writeValueAsBytes(Map.of("event_id",UUID.randomUUID(),"event_type","PrestamoCancelado","event_version",2,"aggregate_version",1,"payload",Map.of("reserva_id",UUID.randomUUID())))));assertEquals(0,processed.count());}
  @Test void seguridadNoCreaUsuariosNiHabilitaBasicOFormLogin()throws Exception{assertTrue(webContext.getBeansOfType(org.springframework.security.core.userdetails.UserDetailsService.class).isEmpty());var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup(webContext).apply(org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity()).build();mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/reservas").header("Authorization","Basic dXNlcjpwYXNz")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().doesNotExist("WWW-Authenticate"));mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/login")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().doesNotExist("Location"));mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/v3/api-docs")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/actuator/health/liveness")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());}
  @Test void openApiAutenticadoExponeFirebaseBearerEnLasNueveOperaciones()throws Exception{var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup(webContext).apply(org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity()).build();String body=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/v3/api-docs").with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user("firebase-uid"))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.components.securitySchemes.firebaseBearer.scheme").value("bearer")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.security[0].firebaseBearer").isArray()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.paths['/api/v1/solicitudes'].post.responses['201']").exists()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.paths['/api/v1/solicitudes/{id}/aceptacion'].post.responses['201']").exists()).andReturn().getResponse().getContentAsString();assertEquals(9,body.split("\"operationId\"",-1).length-1);}
  private boolean attempt(UUID id){try{service.aceptarSolicitud(lender,id);return true;}catch(BusinessConflictException e){return false;}}
  private UUID pending(UUID borrower){UUID id=UUID.randomUUID();Instant now=Instant.now();var terms=new CondicionesAcordadas(new BigDecimal("10.00"),null,"PEN","Campus","uso","entrega","devolucion","cancelacion");solicitudes.saveAndFlush(SolicitudEntity.nueva(id,publication,borrower,lender,new PeriodoPrestamo(LocalDateTime.of(2026,11,10,9,0),LocalDateTime.of(2026,11,12,9,0)),terms,now));return id;}
  private byte[] loanEvent(UUID eventId,String type,long version,UUID reservationId)throws Exception{return json.writeValueAsBytes(Map.of("event_id",eventId,"event_type",type,"event_version",1,"aggregate_id",reservationId,"aggregate_version",version,"occurred_at",Instant.now(),"correlation_id","corr","payload",Map.of("reserva_id",reservationId)));}
  private void consumeUnchecked(byte[] event){try{consumer.consume(event);}catch(Exception exception){throw new RuntimeException(exception);}}
  @TestConfiguration static class CatalogStubConfiguration{@Bean @Primary TestCatalogo testCatalogo(){return new TestCatalogo();}}
  static class TestCatalogo implements CatalogoPort{final AtomicReference<UUID> owner=new AtomicReference<>();public PublicacionSnapshot obtenerSnapshot(UUID id,PeriodoPrestamo period){return new PublicacionSnapshot(id,owner.get(),true,true,new CondicionesAcordadas(new BigDecimal("10.00"),null,"PEN","Campus","uso","entrega","devolución","cancelación"));}}
}
